/* Professor-style rewrites (see src/QUESTION-STYLE.md, from a graded Exam 2).
   Same ids, same correct facts; wording, distractors and format match the real exam.
   Applied on top of data.js / exam3.js before the app starts. */
(() => {
  const R = {"bank-1":["Pay relationships among organizations, reflected in how an organization’s pay compares to that of its competitors, are known as:",["Internal Alignment","External Competitiveness","Compa-Ratio","Federally Mandated Pay Parity"],1,"External competitiveness is about pay relationships AMONG organizations (pay relative to competitors). Pay relationships within one organization are internal alignment (Exam 1)."],"bank-2":["A compensation manager recommends that the organization deliberately set pay for a role below the market average. Which policy is it following?",["Market Lead Policy","Market Match Policy","Broad Banding","Market Lag Policy"],3,"Lag = below market, match = equal to market, lead = above market."],"bank-3":["In practice, an organization expresses external competitiveness by setting its pay level and by:",["Writing job descriptions for every benchmark job","Determining its pay mix relative to competitors","Classifying jobs as exempt or non-exempt, which federal law requires before any pay level can be set","Running performance appraisals"],1,"The two levers are pay level (above, below, or equal to competitors) and pay mix relative to competitors."],"bank-4":["Which of the following is NOT included when calculating an organization’s pay level?",["Number of job applicants","Bonuses","Benefits","Value of stock holdings"],0,"Pay level = (base + bonuses + benefits + value of stock holdings) ÷ number of employees; the number of applicants is not part of it."],"bank-5":["A compensation manager proposes calculating the organization’s pay level from base pay alone. According to the lecture video, why is this approach flawed?",["Base pay is confidential and cannot be used","The FLSA prohibits using base pay alone in pay level calculations","Compensation is much more than base pay, since bonuses, benefits, and stock also cost the company money","Base pay is always at the market rate, so it adds no information"],2,"Bonuses, benefits, and stock all cost the company money, so they all count toward pay level."],"bank-6":["The various types of payments, or pay forms, that make up total compensation are called:",["Pay Level","Pay Range","Pay Grade","Pay Mix"],3,"Pay mix = the forms (base, bonus, benefits, stock). Pay level = the average of all of it."],"bank-7":["What are the two objectives of pay level and pay mix decisions?",["Comply with the FLSA and reduce taxes","Control costs/increase revenues, and attract/retain employees","Build pay grades and run salary surveys","Increase seniority and reduce turnover"],1,"(1) Control costs and increase revenues, where labor costs = pay level × # employees. (2) Attract and retain employees."],"bank-8":["An HR analyst finds that pay for an HR generalist differs between automotive and healthcare employers. Why is there no single “going rate” in the labor market for a job?",["The government sets different minimum wages for each industry","Salary surveys are always inaccurate and should never be relied on","Different employers set different pay levels and define the same role differently","Unions set all market rates"],2,"Employers set different pay levels and define the same role differently; the prof’s example is that an HR generalist in automotive is a different job than an HR generalist in healthcare."],"bank-9":["The three groups of factors that shape external competitiveness are:",["Labor market, product market, and organization factors","Occupation, geography, and competitors","Trait, behavior, and goal factors","Seniority, merit, and incentive factors"],0,"Labor market, product market, and organization factors shape external competitiveness. Occupation/geography/competitors define the RELEVANT MARKET, which is a different list."],"bank-10":["Which of the following is NOT one of the four basic assumptions of labor market theories?",["Employers always seek to maximize profits","People are all the same and interchangeable","The markets employers face are competitive","Employees value nonmonetary rewards more than pay"],3,"The 4 assumptions: maximize profits · people are interchangeable · pay rates reflect all costs of employment · markets are competitive. The prof says none of them are fully true."],"bank-11":["In lecture, the professor noted that an HR professional could not simply go work as a nurse. Which labor market assumption does this example disprove?",["Employers always seek to maximize profits","Pay rates reflect all costs of employment","People are all the same and interchangeable","The markets employers face are competitive"],2,"People have different skills, knowledge, and experience, so they aren’t interchangeable."],"bank-12":["The additional output from employing one more person, with other production factors held constant, is called the:",["Marginal Product of Labor","Marginal Revenue of Labor","Efficiency Wage","None of the answer choices are correct"],0,"Product = output. Marginal revenue is the added dollars that person generates, not the added output."],"bank-13":["A compensation manager estimates the additional revenue the firm would generate by employing one more person, holding all other factors constant. This figure is known as the:",["Marginal Product of Labor","Pay Level","Marginal Revenue of Labor","Range Differential"],2,"Marginal revenue of labor is the added revenue; marginal product is the added output, and output can be high while revenue stays low if demand is weak. A single employer’s demand for labor lines up with the marginal product of labor."],"bank-14":["An employer pays high wages based on efficiency wage theory. High wages are expected to lower labor costs in all of the following ways EXCEPT:",["Attracting higher-quality applicants","Increasing the number of pay grades","Lowering turnover","Reducing the need for supervision"],1,"The 5: better applicants · lower turnover · more worker effort · less shirking · less need for supervision. Adding pay grades is not one of them."],"bank-15":["In efficiency wage theory, “shirking behavior” refers to:",["Refusing overtime, which the FLSA always permits","Negotiating starting pay","Leaving for a competitor","Wasting time on the job"],3,"Shirking = wasting time on the job; the prof noted we spend only about 51% of the workday actually working. Higher wages should reduce shirking."],"bank-16":["The effect a pay strategy has on the composition of the workforce (who is attracted and who is retained) is called:",["Signaling","Sorting","Survey Leveling","Broad Banding"],1,"Sorting = who ends up coming and staying. Signaling = the employer deliberately designing pay to communicate what behavior it wants."],"bank-17":["An employer deliberately designs its pay level and pay mix to communicate to prospective and current employees which behaviors it wants. Which concept is the employer using?",["Sorting","Quoted-Price Market","Signaling","Benchmark Conversion"],2,"Signaling is deliberate, aimed at both prospective and current employees; sorting is the resulting effect on who comes and stays."],"bank-18":["Which of the following does NOT affect the supply of labor?",["Geographic barriers to mobility","Union requirements","Lack of information about job openings","Marginal revenue of labor"],3,"Supply factors: geographic barriers · union requirements · lack of job info · degree of risk · degree of unemployment · nonmonetary aspects. Marginal revenue is on the DEMAND side."],"bank-19":["During COVID, an HR manager observes that some workers chose to stay on enhanced unemployment instead of returning to work. Which supply-side factor does this illustrate?",["Union requirements","Degree of unemployment","Geographic barriers to mobility","Degree of risk"],1,"This was the prof’s example for the degree of unemployment (and unemployment benefits) affecting labor supply."],"bank-20":["An organization struggles to attract applicants because a department manager is known for micromanaging and being unfriendly. Which labor supply factor does this illustrate?",["Degree of unemployment","Union requirements","Nonmonetary aspects of jobs","Marginal product of labor"],2,"Things other than pay about the job (like the manager) change who is willing to supply their labor."],"bank-21":["Which of the following lists the product market factors that affect an employer’s ability to pay?",["Occupation, geography, competitors","Productivity of labor, technology employed, level of production relative to plant capacity","Trait, comparison, behavioral","None of the answer choices are correct"],1,"Productivity, technology, and production relative to plant capacity are product market factors; in the video the prof also named the degree of competition and the level of product demand. Occupation/geography/competitors define the relevant market instead."],"bank-22":["A regular full-time nurse earns about ______ of the base rate, ______ benefits, and the hospital ______ an agency fee.",["132%, gets no, pays no","150%, gets, pays","100%, gets, pays no","150%, gets no, pays"],2,"Regular 100% / benefits / no fee · Pool 132% / no benefits / no fee · Registry and Traveler 150% / benefits paid by the agency / hospital pays an agency fee."],"bank-23":["A hospital staffs a shift with a registry nurse (an agency employee working at multiple area hospitals). Relative to the base rate, the registry nurse earns about:",["100%","132%","200%","150%"],3,"Registry = 150%, benefits paid by the agency, and the hospital pays the agency a fee. 132% is the pool nurse rate."],"bank-24":["The nurse pay table (e.g., regular, pool, registry, and traveler nurses) is the slide example of:",["Efficiency Wage Theory","Segmented supplies of labor with different going rates","Broad Banding","Forced Distribution"],1,"One occupation can have several labor supplies, each at its own going rate."],"bank-25":["Which of the following lists the organization factors that shape pay?",["Industry & technology, employer size, people’s preferences","Supply, demand, marginal revenue","Quoted-price and bourse markets","Mean, median, mode"],0,"Industry & technology, employer size, and people’s preferences are organization factors; in the video the prof also mentioned strategy and individual managers."],"bank-26":["A compensation manager compares pay at a large employer with pay at smaller firms. According to the slides, how does employer size typically relate to pay?",["Bigger organizations typically pay more, usually because they have more revenue","Bigger organizations typically pay less","Federal law requires bigger organizations to have more pay grades","Bigger organizations rely less on salary surveys"],0,"Employer size: bigger organizations typically pay more because they usually have more revenue."],"bank-27":["An analyst notes that pay at bowling businesses is constrained because the bowling industry is declining. Which organization factor does this illustrate?",["Industry","Union requirements","Signaling","Degree of risk"],0,"Whether an industry is growing or dying affects its ability to pay."],"bank-28":["What three factors are commonly used to define the relevant labor market?",["Size, industry, technology","Lag, match, lead","Occupation, geography, competitors","None of the answer choices are correct"],2,"Occupation = skills/knowledge · Geography = willingness to relocate, commute, or work virtually · Competitors = same product/service and labor markets."],"bank-29":["A company widens its recruiting search to people willing to commute, relocate, or work remotely. Which relevant-market factor is it adjusting?",["Geography","Occupation","Competitors","Technology"],0,"Geography covers relocating, commuting, or being a virtual employee."],"bank-30":["An HR analyst is deciding how much weight to give product-market competitor data. This data should get MORE weight when:",["Labor supply is very responsive to pay changes","Product demand does not respond to price","Labor costs are a large share of total costs","Skills transfer easily to any industry"],2,"All 4 conditions: skills are specific to the product market · labor costs are a large share of total costs · product demand responds to price · labor supply does NOT respond to pay."],"bank-31":["Product-market data gets more weight when the supply of labor is:",["Very responsive to changes in pay","Unionized, which always mandates product-market pricing","Remote","Not responsive to changes in pay"],3,"Trap: it’s “NOT responsive” to changes in pay, not very responsive."],"bank-32":["A firm is considering offshoring work to a country with lower average labor costs. What should the compensation manager expect about productivity there?",["Productivity will automatically be higher","Average productivity tends to be lower","There will be no intellectual property risk","Customer reactions will always be better"],1,"Countries with lower average labor costs also tend to have lower average productivity. Other offshoring factors: IP theft risk · agency theory monitoring costs · customer reactions."],"bank-33":["After an organization moves production to a country with poor labor conditions, customers boycott the brand. Which offshoring factor does this illustrate?",["Agency theory","Lower productivity","Intellectual property theft","Customers’ reactions"],3,"This was the prof’s China example: customers’ reactions must be considered."],"bank-34":["Which of the following IS a desired consequence of competitive pay-level and pay-mix decisions?",["Increase voluntary turnover","Increase pay-related work stoppages","Increase the applicant pool","Decrease union-free status"],2,"The goals: contain labor costs · increase the applicant pool · increase applicant quality/experience · reduce voluntary turnover · increase the probability of union-free status · reduce pay-related work stoppages."],"bank-35":["A manager suggests letting an employee leave rather than giving a fair raise. According to the professor, replacing an employee typically costs about:",["The same as a raise","About three times what a fair raise would cost","Half their salary","Nothing, if the job is posted on Indeed"],1,"Replacing someone costs about three times a fair raise, which is the reason to pay competitively and retain people instead of letting them flip jobs for more money."],"practice-1":["A retailer posts “Starting pay $17/hr” on every job ad. Which type of market is this?",["Quoted-Price Market","Bourse Market","Efficiency Wage","Segmented Supply"],0,"The employer quotes a set rate to all applicants, which is a quoted-price market. A bourse market is one where pay is negotiated with the candidate."],"practice-2":["An organization pays above market to cut turnover and supervision costs. According to which theory is it acting?",["Tournament Theory","Human Capital Theory","Efficiency Wage Theory","Agency Theory"],2,"Efficiency wage theory says above-market pay can lower labor costs through lower turnover and less need for supervision."],"practice-3":["A startup establishes a package of low base pay plus large performance bonuses, and it attracts risk-takers. This is best described as:",["Market Match","Sorting and Signaling","Broad Banding","Survey Leveling"],1,"The pay design signals what the employer values and sorts who is attracted (risk-takers); market match would mean pay equal to market."],"practice-12":["Product-market competitor data should get MORE weight when:",["Labor supply is very responsive to pay","Labor costs are a small share of total costs","Product demand ignores price","Employee skills are specific to the product market"],3,"Skills specific to the product market increase the weight of product-market data; each of the other options is the opposite of a condition that does."],"practice-13":["A travel nurse typically earns about what percent of a regular full-time nurse’s hourly wage?",["100%","150%","132%","200%"],1,"Traveler nurses earn about 150%; 132% is the pool nurse rate and 100% is the regular nurse."],"practice-14":["A hospital pays its pool nurses about 132% of what regular nurses earn. What is the main reason?",["Union rules always require the premium","They are agency employees","They get no benefits and there’s no agency fee","They only work nights"],2,"Pool nurses get no benefits and the hospital pays no agency fee, so their pay rate is higher; agency employees are the registry and traveler nurses."],"practice-15":["Per the professor, a market lead or lag policy usually sets pay how far from the market?",["15–25%","30% or more","0–1%","2–10%"],3,"Lead and lag policies are usually about 2–10% above or below the market."],"practice-16":["Caterpillar moves most of a Peoria team to India, and the company now has to spend resources monitoring the workers’ effort and output. Which theory explains this?",["Agency Theory","Efficiency Wage Theory","Human Capital Theory","Equity Theory"],0,"Agency theory covers the cost of monitoring workers’ effort and output."],"practice-17":["A car salesperson is paid mostly on commission, with a draw advanced against it. This pay arrangement shows:",["High risk propensity","Low risk propensity","Market match","None of the answer choices are correct"],0,"Pay that depends mostly on commission puts much of it at risk, which fits a high risk propensity."],"practice-18":["Which of the following is NOT a goal (consequence) of competitive pay-level decisions?",["Reduce voluntary turnover","Increase the probability of union-free status","Increase pay-related work stoppages","Increase the applicant pool"],2,"The goal is to REDUCE pay-related work stoppages, not increase them; the other three are real goals."],"practice-19":["A CHRO candidate negotiates for pay above the posted range plus a pay review after one year. Which type of market is this?",["Quoted-Price Market","Bourse Market","Segmented Supply","None of the answer choices are correct"],1,"Negotiating terms beyond the posted range is a bourse market; a quoted-price market posts a set rate."],"practice-20":["An HR team plans to survey employees about their pay preferences. Why should the survey be anonymous?",["People answer more truthfully without fear of retaliation","The FLSA requires it","ERISA requires all pay surveys to be anonymous","Anonymous surveys are always cheaper"],0,"Anonymity lets people answer truthfully without fear of retaliation; neither the FLSA nor ERISA requires it."],"bank-60":["Periodic additions to base pay awarded according to an employee’s length of service are known as:",["Merit Pay","Seniority (Longevity) Pay","Pay-for-Knowledge","Profit Sharing"],1,"Seniority (longevity) pay makes periodic additions to base pay according to length of service, not performance."],"bank-61":["An employer justifies automatic raises for tenure by arguing that employees become more valuable over time. Which theory supports this practice?",["Agency Theory","Efficiency Wage Theory","Tournament Theory","Human Capital Theory"],3,"Human capital theory says employees become more valuable over time, and it is the justification for seniority pay."],"bank-62":["What is one of the major disadvantages of seniority pay?",["It avoids the perception of favoritism","It provides no incentive to improve","It facilitates administration","Employees feel treated fairly"],1,"Disadvantages: poor fit with competitive strategies · no incentive to improve · growing costs. The other three options are advantages."],"bank-63":["An organization grants the same raise to every employee with the same tenure. Why does this seniority pay approach avoid the perception of favoritism?",["Raises depend only on time with the company, not on performance or relationships","Managers personally select who receives raises","Federal law prohibits managers from reviewing seniority raises","It relies on a Forced Distribution system"],0,"Everyone with the same tenure gets the same raise, so managers’ opinions and relationships play no role."],"bank-64":["Permanent pay increases awarded for performance are known as:",["Incentive Pay","Seniority Pay","Merit Pay","Pay-for-Knowledge"],2,"Merit = permanent and based on performance. Seniority = permanent and based on time. Incentive = nonrecurring."],"bank-65":["According to the slides, what was the approximate average merit increase in 2025?",["8%","1%","15%","3.3%"],3,"The slide says 3.3%. The prof said it was higher in 2023–24 and tied the drop to the reversal of the 2024 FLSA salary threshold increase."],"bank-66":["Pay raises large enough that employees see them as a real change in compensation for their performance are called:",["Just-Meaningful Pay Increases","Spot Bonuses","Cost-of-Living Adjustments","Efficiency Wages"],0,"Just-meaningful pay increases are one of the elements of an effective merit program."],"bank-67":["A compensation manager is designing a merit pay program. Which of the following is NOT an element of an effective merit pay program?",["Objective and subjective indicators of performance","Periodic performance reviews","Equal raises for everyone, regardless of performance","Realistic and attainable standards"],2,"Pay increases have to reflect performance, so equal raises for everyone don’t belong. Just-meaningful increases are also on the list."],"bank-68":["An organization is setting up a new performance appraisal process. Which practice should come first?",["Rank all employees","Set bonus amounts","Hold formal appeal hearings","Conduct a job analysis"],3,"Order: job analysis → incorporate the results into ratings → train supervisors → formal appeals/review process."],"bank-69":["A company trains every supervisor on how to use its performance appraisal system. What is the main reason for this training?",["So all departments rate employees consistently","To avoid FLSA claims","To reduce the number of pay grades","Because Federal law always strictly mandates annual rater certification"],0,"Training means everyone uses the same documents in the same way, so ratings are consistent across departments."],"bank-70":["A formal appeals process for performance ratings mainly exists because:",["The law requires quarterly reviews","Employees may feel they were rated unfairly or discriminated against","Managers want to conduct fewer reviews","None of the answer choices are correct"],1,"An appeals process gives employees a voice if they feel they were rated unfairly or discriminated against."],"bank-71":["An appraisal system that asks raters to evaluate employees’ traits or characteristics is known as a:",["Comparison System","Behavioral System","Trait System","Goal-Oriented System"],2,"Trait = characteristics · Comparison = vs other employees · Behavioral = displays successful behaviors · Goal-oriented = progress toward strategic objectives."],"bank-72":["According to the professor, the most common performance appraisal system is the:",["Trait System","Comparison System","Goal-Oriented System","Behavioral System"],3,"Behavioral systems are the most common: employees are rated (e.g., 1–5) on job performance behaviors."],"bank-73":["A company evaluates its managerial and professional employees on their progress toward strategic objectives. Which appraisal system is it using?",["Goal-Oriented System","Trait System","Comparison System","Behavioral System"],0,"This is the slide definition of a goal-oriented system, used mainly for managerial and professional employees."],"bank-74":["An organization sorts employees into performance groups (e.g., top 10%, next 20%, and so on), and the bottom group is likely terminated. This appraisal method is called:",["Paired Comparison","Forced Distribution","Behavioral System","Broad Banding"],1,"Forced distribution is a type of comparison system. The prof warned it can be harsh and create litigation risk."],"bank-75":["A manager compares two employees side by side to decide which one performs better. This method is known as:",["Forced Distribution","Trait System","Paired Comparison","Goal-Oriented System"],2,"Paired comparison is another comparison-system type; forced distribution sorts everyone into set percentage groups instead."],"bank-76":["According to the professor’s statistics, approximately what percentage of managers are dissatisfied with their current performance management process?",["95%","71%","43%","18%"],0,"95% of managers are dissatisfied. Other stats: roughly 63–71% of organizations do annual reviews, about 18% semiannual, 8% quarterly."],"bank-77":["An HR director is considering using AI to conduct performance reviews. Which of the following is a challenge of this approach?",["Real-time feedback","Saves managers time","Better data collection","Privacy concerns and ignoring outside challenges employees face"],3,"AI can’t account for things like a divorce or an illness. The other three options are positives."],"bank-78":["Which of the following is NOT part of the pay-for-performance link?",["Link appraisals to business goals","Give everyone the same raise","Differentiate among performers","Communicate expectations"],1,"The link: tie appraisals to business goals · analyze jobs · establish effective appraisals · empower employees · differentiate performers · communicate expectations."],"bank-79":["Which of the following does NOT determine how incentive pay fluctuates?",["Years of service","A preestablished formula","Individual or group goals","Company earnings"],0,"Years of service = seniority. Incentive pay adds to base pay on a nonrecurring basis, controls costs, and motivates through explicit goal setting."],"bank-80":["A car dealership cut its monthly sales goal from 150 cars to 110 during a slow winter month. Which property of incentive pay allows the employer to make this change?",["It is a permanent addition to base pay","It is based on seniority","It is nonrecurring, so goals can be reset each period","It is required by the FLSA"],2,"Incentives have to be re-earned each period, so the employer can adjust the targets."],"bank-81":["An annual salary or hourly wage that is increased periodically on the basis of seniority or merit is known as:",["Incentive Pay","Traditional Pay","Commission-Only Pay","Profit Sharing"],1,"Traditional pay increases are permanent. Incentive pay increases are nonrecurring."],"bank-82":["Plans that tie employee compensation to the company’s performance over a short time frame are known as:",["Individual Incentives","Group Incentives","Merit Plans","Company-Wide Incentives"],3,"Individual = rewards independent work · Group = promotes collaborative behavior · Company-wide = tied to company performance."],"bank-83":["Which incentive category promotes supportive, collaborative behavior among employees?",["Group Incentives","Individual Incentives","Seniority Pay","Referral Plans"],0,"This is the slide definition for group plans; individual plans reward independent work."],"bank-84":["A manager receives a bonus for meeting the division’s sales, profit, or production objectives. Which type of incentive is this?",["Piecework Plan","Behavioral Encouragement Plan","Management Incentive Plan","Signing Bonus"],2,"Management incentive plans are based on division objectives."],"bank-85":["An employer pays an employee for a specific behavioral accomplishment (e.g., an innovation or strong collaboration). This is called a:",["Referral Plan","Behavioral Encouragement Plan","Piecework Plan","Company-Wide Plan"],1,"Behavioral encouragement plans pay for specific behavioral accomplishments."],"bank-86":["A manager hands an employee a $100 gift card for great work this past week. This is known as a:",["Merit Increase","Signing Bonus","Profit Sharing","Spot Bonus"],3,"A spot bonus is a small monetary gift for outstanding work over a reasonably short period."],"bank-87":["A bonus paid to an employee for recruiting a highly qualified new hire is known as a:",["Referral Plan","Signing Bonus","Spot Bonus","Management Incentive"],0,"A referral plan rewards the employee who recruited the hire. A signing bonus goes to the NEW hire to get them to accept the offer."],"bank-88":["A plan in which workers earn extra for every item produced over a designated production standard is called a:",["Gainsharing Plan","Piecework Plan","Seniority Plan","None of the answer choices are correct"],1,"This is a piecework plan, the plan type behind the $3-per-22-units math."],"bank-89":["Which of the following is an advantage of individual (rather than group) incentive programs?",["Greater group cohesion","Easier to develop performance measures","Compatible with America’s individualistic culture","Federal law requires individual incentives for all sales positions"],2,"Individual advantages: relates pay to performance · equitable distribution · ownership mentality · fits an individualistic culture. Greater cohesion and easier performance measures are GROUP advantages."],"bank-90":["A bank splits its team bonus pool among team members according to each member’s contribution to the team’s goals. Which allocation method is the bank using?",["Equal payments to all members","Differential payments according to base pay","Forced Distribution","Differential payments based on contribution to goals"],3,"The prof said Jeff Stewart’s bank uses contribution-based differential payments."],"bank-91":["What is one of the major advantages of group incentives?",["Greater group cohesion","The free-rider effect","Members’ pay depends on others","Higher turnover"],0,"Group advantages: performance measures are easier to develop · greater cohesion. The disadvantages are free riders (which lead to turnover) and discomfort with others influencing your pay."],"bank-92":["A compensation manager notices that on teams paid through group incentives, some members coast while others carry the workload. If this free-rider effect continues, it is most likely to lead to:",["Lower labor costs","Better signaling","Higher turnover among high performers","A higher range midpoint"],2,"High performers get frustrated carrying coasters and leave."],"bank-93":["In most situations, incentive pay should:",["Replace traditional pay entirely","Complement traditional pay","Be paid only annually, as Federal law requires","Be based on seniority"],1,"Commission-only roles replace traditional pay, but usually incentives complement it. The time horizon for goals should be attainable and realistic."],"practice-5":["Which of the following is a feature of incentive pay rather than merit pay?",["A permanent addition to base pay","Based on years of service","A nonrecurring payment that must be re-earned","Raises the range midpoint"],2,"Incentive pay is nonrecurring and must be re-earned; merit pay is a permanent addition to base, and years of service describes seniority pay."],"practice-6":["A manager ranks all 12 employees in the department from best to worst. Which type of appraisal system is this?",["Trait System","Behavioral System","Goal-Oriented System","Comparison System"],3,"Ranking employees against each other is a comparison system; a trait system evaluates characteristics and a behavioral system rates job behaviors."],"practice-7":["Team members complain that one person coasts while still sharing the group bonus. This is known as the:",["Halo Effect","Free-Rider Effect","Signaling Effect","None of the answer choices are correct"],1,"This is the free-rider effect, a disadvantage of group incentives."],"bank-94":["Which of the following is NOT one of the “top six” things employees value, according to guest speaker Sam Lewis?",["Security","Challenge","Location","Stock Options"],3,"Lewis’s top six are Challenge, Location, Advancement, Money, People and Security. Stock options are not on the list."],"bank-95":["Guest speaker Sam Lewis described hiring a woman for less money because she hated her boss. According to Lewis, which employee value outweighed money in her decision?",["Location","People","Security","Challenge"],1,"People means who you work with and for. Her dislike of her boss mattered more to her than the pay difference."],"bank-96":["Sam Lewis called ______ the “sneaky” value that sits at the top of many employees’ lists without them realizing it.",["Money","Advancement","Security","Challenge"],2,"Security is the sneaky one: some people won’t move for any amount of money."],"bank-97":["An early-career employee looks at a flat organizational chart and concludes, “I’m not going anywhere.” According to Sam Lewis, which employee value matters most at this stage of a career?",["Advancement","Security","Location","Money"],0,"Advancement matters most early in a career, and priorities shift as a career goes on."],"bank-98":["An organization gives employees a raise for each additional year on the job. Under Sam Lewis’s three compensation models, which model is it following?",["Performance","Competency","Time & Tenure","Gainsharing"],2,"Lewis’s three models are Time & Tenure, Performance and Competency; yearly raises are Time & Tenure. Gainsharing is a group incentive, not one of his three models, and most good systems combine all three."],"bank-99":["Sam Lewis’s “manager’s test” for seniority pay asks which question?",["Can the employee’s certified skill actually be used on the job?","Is the starting year used as the baseline for targets reasonable?","No test is needed, because federal law requires an automatic raise after every year of service","What does an additional year of experience change in this role?"],3,"If an extra year changes nothing in the role, pay stays put: the job is the limiter, not the person. The skill-use and baseline questions belong to Lewis’s competency and performance-pay tests."],"bank-100":["After a plant installs new equipment, output jumps and production workers ask for the productivity bonus. According to Sam Lewis’s tests for performance pay, which test does this bonus fail?",["Clarity","Influence (Line of Sight)","Relevant","Used"],1,"The four performance-pay tests are Influence, Clarity, Balance and Baseline; the workers didn’t cause the gain, so Influence fails (the new equipment also shifts the baseline). Relevant and Used are competency-pay tests."],"bank-101":["A production line runs at 110% of rate but produces 80% scrap because its bonus rewards only speed. Which of Sam Lewis’s performance-pay tests does the plan fail?",["Balance","Clarity","Baseline","Applied"],0,"Balance means the measure can’t reward one result (speed) at the expense of another (quality)."],"bank-102":["A compensation manager sets a bonus target using the 2008 housing crash as the starting year. According to Sam Lewis, which test does this plan fail?",["Influence","Balance","Baseline","Relevant"],2,"A bad starting year makes the targets far too easy, so the plan fails the Baseline test."],"bank-103":["Sam Lewis held 8 meetings a month, including one at 11 p.m., to explain to employees how their bonus was calculated. Which performance-pay test was he addressing?",["Baseline","Used","Balance","Clarity"],3,"Clarity: people must understand how the payout is calculated."],"bank-104":["Sam Lewis’s plant-wide STAR bonus (productivity + quality + expenses, with everyone in the pool) was modeled on the ______.",["Hay System","Forced Distribution system","Scanlon Plan (Gainsharing)","Piecework Plan"],2,"STAR was a Scanlon-style gainsharing plan. Lewis also cited Herzberg and open-book management, and he prefers bonuses for smaller groups."],"bank-105":["An employer gave extruder operators a raise for certifying on the calender line, but none of them was ever moved there. According to Sam Lewis, which competency-pay test does this fail?",["Relevant","Used","Applied","Clarity"],1,"The three competency tests are Relevant, Applied and Used. The company never used the skill, so Lewis eliminated the pay."],"bank-106":["All maintenance workers were paid for completing hydraulics training, but a later evaluation showed almost none of them could actually do the work. Which of Sam Lewis’s competency-pay tests does this fail?",["Used","Baseline","Relevant","Applied"],3,"The skill was never truly Applied. Lewis’s lesson: evaluate first, then pay."],"bank-107":["According to Sam Lewis, pay rises as a job shifts from managing ______.",["Ideas → people → things","People → things → ideas","Things → people → ideas","None of the answer choices are correct"],2,"Entry-level jobs manage things, managers manage people and the CEO manages mostly ideas. This ties to point systems like Hay."],"bank-108":["A company introduces an individual bonus for each completed work order. What is the most likely unintended consequence?",["Cherry-picking of easy orders and rushed repairs","More mentoring of newer workers","A move to Broad Banding of the pay structure","The plan is automatically void, because federal law prohibits per-order bonuses"],0,"Per-order bonuses lead to cherry-picking and rushed work, with no teamwork and no teaching. Lewis’s fix was a 4-tier maintenance pay system that rewarded seniors for bringing up the next tier."],"bank-109":["Senior “wizard” technicians refuse to share their “little black book” of knowledge with newer workers. According to Sam Lewis, they do this because it protects their:",["Security","Challenge","Advancement","Location"],0,"Knowledge = power = job security. The answer is to reward mentoring through tiered, skill-based pay."],"bank-110":["Rivian entered Normal at $17/hr, quickly went to $22/hr, and forced local plants to raise their pay. This situation is an example of:",["A labor-market shock driving external competitiveness","Internal Alignment","Seniority (Time & Tenure) Pay","A rule requiring employers to match any new entrant’s wage within the same county"],0,"A new employer changed the local labor market, so other employers had to respond to stay competitive. Lewis told clients, “Your pay has to go up.”"],"bank-111":["According to Sam Lewis, a salary survey does NOT tell an organization:",["What competitors pay","Whether its rewards support the right behavior","Whether its pay is in the right range","Current market rates"],1,"Surveys answer only the competitiveness question. They also don’t tell you what different employees value."],"bank-112":["A restaurant chain (e.g., Cracker Barrel) awards star pins to its servers. Which element of the total rewards portfolio is the chain using?",["Cash","Benefits","Flexibility","Recognition"],3,"The total rewards portfolio is cash, benefits, flexibility, growth opportunities and recognition; star pins are Recognition. The goal is to send employees a coherent signal."],"bank-113":["Sam Lewis used the DISC analogy to make which point about compensation design?",["Organizations should hire only dominant personality types","Compensation should be designed for the whole team, not one type of person","Personality test results must always be used to set individual pay","None of the answer choices are correct"],1,"A room full of one personality type doesn’t work (the Jordan vs. Riley example), so pay plans should fit the whole team."],"bank-114":["Performance pay fails when employees can’t influence the result. Competency pay fails when ______.",["employees are too senior","the salary survey is out of date","the skill isn’t used","pay is set above market"],2,"This is the “common trap” line from the Lewis notes: paying for a skill the company never uses. As he put it, don’t pay a PhD rocket scientist to assemble widgets."],"bank-36":["The systematic process of collecting and making judgments about the compensation paid by other employers is called:",["An Employee Attitude Survey","A Salary Survey","Job Analysis","A Performance Appraisal"],1,"A salary survey collects and judges other employers’ pay; surveys turn an external pay policy into actual pay levels, mix, and structures."],"bank-37":["A compensation manager is documenting why the organization participates in salary surveys. Which of the following is NOT a purpose of a salary survey?",["Estimate competitors’ labor costs","Establish or price a pay structure","Adjust the pay level in response to competitors’ changing rates","Rank employees for a Forced Distribution system"],3,"The 5 purposes are: adjust pay level · set pay mix · establish/price the structure · analyze pay-related problems · estimate competitors’ labor costs. Forced distribution is an appraisal method, not a survey purpose."],"bank-38":["An HR analyst has been asked to use salary survey data to price the organization’s entire pay structure. Which approach should the analyst use?",["Benchmark-Job Approach","Low-High Approach","Survey Leveling, which is always strictly mandated whenever survey data is used","Forced Distribution"],0,"To price the entire structure, select benchmark jobs that span the whole structure. The low-high approach is for skill/competency-based structures."],"bank-39":["Using the lowest- and highest-paid benchmark jobs as anchors to price a skill- or competency-based structure is called the:",["Benchmark Conversion","Market Match Policy","Low-High Approach","Benchmark-Job Approach"],2,"In the low-high approach, the lowest and highest benchmark wages serve as anchors for skill-based or generic structures."],"bank-40":["During a market pricing analysis, an HR analyst finds that the company’s job does not match any survey job, so the analyst runs the survey jobs through the company’s own job evaluation system to quantify the difference. What procedure is the analyst applying?",["Benchmark Conversion / Survey Leveling","Low-High Approach","Broad Banding","Paired Comparison"],0,"Survey leveling (benchmark conversion) is used when a job is similar but not identical to a survey job."],"bank-41":["A compensation analyst reviewing survey results notices anomalies in the data. According to the slides, what is the best way to answer questions about these anomalies?",["Delete them, since Federal law prohibits using outlier data","Average them into the overall results","Analyze them alone","Discard the entire survey"],2,"Anomalies should be analyzed alone to answer questions such as: does one company dominate? do all employers show similar patterns? are there outliers?"],"bank-42":["The survey analysis tool that helps an analyst visualize the data and may highlight outliers is known as a:",["Central Tendency","Range Differential","Compa-Ratio","Frequency Distribution"],3,"A frequency distribution lets you visualize the data and spot outliers. Central tendency reduces the data to one number, and variation is the spread around that number."],"bank-43":["Quartiles and percentiles are measures of:",["Central Tendency","Variation","Pay Mix","None of the answer choices are correct"],1,"Variation is the distribution of rates around the central tendency, which quartiles and percentiles describe."],"bank-44":["An HR analyst condenses hundreds of survey pay rates for a benchmark job into a single number (e.g., mean, weighted mean, median, or mode). This kind of measure is called:",["Variation","Frequency Distribution","Central Tendency","Anomaly Analysis"],2,"Central tendency reduces a large amount of survey data to a single number. The slides stress that the difference between mean and weighted mean is important."],"bank-45":["A pay range exists whenever:",["Two or more rates are paid to employees in the same job","A job is evaluated at more than 500 points","An employee is paid above the range maximum","The company uses Broad Banding, which automatically creates a range for every job"],0,"A range exists whenever two or more rates are paid in the same job; it reflects differences in performance or experience that the employer wants to recognize."],"bank-46":["A compensation manager reviews an employee who has received consistently high performance ratings. According to the slides, where should this employee’s pay be positioned?",["At the range minimum, since pay must never rise above the minimum without a promotion","Above the market median and the range midpoint","Frozen at the current rate","In a lower pay grade"],1,"This comes straight from the slides: consistently high performers should move above the market median and range midpoint."],"bank-47":["Which of the following is NOT an opportunity that pay ranges give managers?",["Recognize individual performance differences with pay","Meet employees’ expectations that pay will rise over time in the same job","Eliminate the need for performance appraisals","Encourage employees to stay with the organization"],2,"The 3 on the slide: recognize performance · meet expectations of increases over time · encourage retention. Ranges do not remove the need for appraisals."],"bank-48":["A compensation team is building a new set of pay grades and ranges. What should be the first step?",["Set the range maximum for each grade","Calculate compa-ratios for all employees","Freeze the pay of all overpaid employees","Group jobs that are substantially equal for pay purposes into a grade"],3,"The first step is grouping substantially equal jobs into a grade, because every job in one grade shares the same pay range."],"bank-49":["According to the slides, a pay grade’s midpoint is determined by:",["Averaging the weighted means of the positions clustered in the grade","The rate of the highest-paid job in the grade","Doubling the range minimum","Federal law, which sets a required midpoint for each grade"],0,"This is Step 1 on the “How to establish pay grades” slide: average the weighted means of the positions clustered in the grade."],"bank-50":["Range differentials for most pay ranges typically fall between:",["2–10%","10–30%","30–50%","50–100%"],1,"Most range differentials fall between 10–30%. Don’t confuse this with lead/lag, which is 2–10% off the market."],"bank-51":["An HR analyst discovers that an employee whose work is satisfactory is paid below the pay range. What procedure should HR apply?",["Freeze the employee’s pay until the range is adjusted","Terminate the employee, since pay below the range is legally prohibited","Give frequent pay increases to bring the employee in line","Take no action"],2,"Underpaid → frequent increases. Overpaid → freeze."],"bank-52":["Most organizations use approximately how many pay grades?",["2–4","5–10","11–17","30–40"],2,"Most organizations use 11–17. The recommendation is no fewer than 5 and no more than 25."],"bank-53":["The recommended minimum and maximum number of pay grades is:",["1 and 10","11 and 17","10 and 30","5 and 25"],3,"No fewer than 5, no more than 25. 11–17 is how many most organizations actually use."],"bank-54":["An organization consolidates its many narrow pay grades into a few wide bands. Which of the following is NOT a feature of this Broad Banding approach?",["Flattens corporate hierarchies","Increases the number of pay grades","Gives managers more latitude in pay decisions","Consolidates pay grades and ranges"],1,"Broadbanding consolidates grades, so it reduces rather than increases them. Its other features: emphasizes teamwork · broadens duties · quicker decision-making."],"bank-55":["A compensation analyst sets a pay grade with a midpoint of $52,000 and a range differential of 15%. What are the range minimum and maximum?",["$46,800 / $57,200","$37,000 / $67,000","$44,200 / $59,800","$44,200 / $61,000"],2,"52,000 × 0.85 = 44,200 · 52,000 × 1.15 = 59,800. Check: both are 7,800 from the mid."],"bank-56":["An organization’s Grade 1 midpoint is $42,000 and its Grade 2 midpoint is $47,040. What is the midpoint differential?",["5,040%","10%","15%","12%"],3,"47,040 ÷ 42,000 = 1.12, so 12%. The $5,040 gap is a dollar difference, not a percentage."],"bank-57":["A firm with 10 employees pays $500,000 in base pay, $50,000 in bonuses, $150,000 in benefits, and $0 in stock. What is the firm’s pay level?",["$70,000","$55,000","$50,000","$700,000"],0,"700,000 ÷ 10 = 70,000. Labor costs = 70,000 × 10 = 700,000, so $700,000 is the total, not the pay level."],"bank-58":["In the formula Pay = (x − xy)(a ÷ b) + xy for a grade that is 200 points wide, b equals:",["200","100","The job’s points","None of the answer choices are correct"],1,"b = half the grade width (200 ÷ 2 = 100). a = job points − the grade bottom."],"bank-59":["An HR analyst is calculating a job’s pay rate from its points. According to the 9/25 review, which rounding rule should the analyst apply?",["Always round up","Always round down","Normal rounding","Keep the exact cents, since rounding pay rates is legally prohibited"],0,"Pay rates: round UP. Building the pay table: normal rounding. Piecework sets: round DOWN."],"practice-4":["An HR analyst discovers that an employee’s pay is above the range maximum. According to the slides, what procedure should HR apply?",["Cut the employee’s pay immediately, as Federal law requires","Give frequent pay increases","Move the employee to a new grade","Freeze the employee’s pay"],3,"Overpaid (above the range maximum) → freeze pay. Frequent increases are for employees paid below the range."],"e3d-q1":["Moore’s Law describes ______.",["Pay Compression between new hires and long-tenured employees","the steady growth in computing power on microchips (CPUs/GPUs)","a federal rule requiring the minimum wage to rise every year","the rising cost of employee benefits"],1,"Moore’s Law says chip power keeps doubling, which drove the tech revolution (CPU → GPU). The other options are unrelated compensation topics."],"e3d-q2":["Which of the following puts the video-meeting technologies from guest speaker Derek Story’s timeline in the correct order?",["Zoom → WebEx → AT&T Picturephone","CU-SeeMe → Zoom → AT&T Picturephone","WebEx → AT&T Picturephone → Zoom","AT&T Picturephone (1964) → CU-SeeMe (1992) → WebEx/GoToMeeting (1995–2004) → Zoom (2010s)"],3,"Derek’s timeline: 1964 Picturephone, 1992 CU-SeeMe, 1995–2004 WebEx and GoToMeeting, 2010–20 Zoom."],"e3d-q3":["On guest speaker Derek Story’s AI timeline, which of the following came FIRST?",["Lloyd’s of London (1689)","Autocorrect","AlexNet","GPT"],0,"The timeline starts with Lloyd’s of London in 1689 (risk and probability), then Markov (1900s), the term “AI” (1950s–60s), autocorrect (90s–00s), AlexNet (2012), Tay (2016), BERT (2018) and GPT (2020)."],"e3d-q4":["Which of the following correctly matches a year to an event on Derek Story’s AI timeline?",["2012 – GPT","2018 – AlexNet","2016 – Microsoft Tay","2020 – BERT"],2,"The correct pairs are 2012 AlexNet, 2016 Microsoft Tay, 2018 BERT and 2020 GPT; the other options swap the years."],"e3d-q5":["A university office receives a request to release a student’s education records. Which law protects these records?",["HIPAA","GDPR","FERPA","COPPA"],2,"FERPA protects student records. HIPAA covers health information, COPPA protects children online and GDPR is EU data privacy."],"e3d-q6":["A campus compliance officer is reviewing which records fall under HIPAA. HIPAA would matter most for which campus data?",["Grades","Course catalog","Parking permits","Student health services records"],3,"HIPAA covers health information (e.g., student health services and child care). Grades fall under FERPA instead."],"e3d-q7":["The privacy law that protects children online is known as:",["COPPA","FERPA","FMLA","ERISA"],0,"COPPA is the Children’s Online Privacy Protection Act. FERPA covers student records."],"e3d-q8":["In Derek Story’s CRAFTY prompt method, the “A” stands for:",["Accuracy","Algorithm","Answer","Audience (who the output is for)"],3,"CRAFTY is Character, Request, Audience, Format/Features, Tone and Your extras/questions; “A” is Audience."],"e3d-q9":["A student begins an AI prompt by telling the tool to act as a professor. Under Derek Story’s CRAFTY method, which element is the student using?",["Request","Character","Tone","Audience"],1,"Character is who the AI should play (e.g., a professor or a student). Audience is who the output is for, which is a common mix-up."],"e3d-q10":["An organization wants to build an AI-friendly culture. According to Derek Story, its AI use should be:",["Kept quiet so employees adopt it quickly","Transparent and aligned with the organization’s cultural values","Banned outright, because federal law prohibits workplace AI use","Restricted to the IT department only"],1,"Derek’s two keys are (1) transparency and (2) alignment with cultural values."],"e3d-q11":["A recruiting director is evaluating an AI screening tool. According to Derek Story, what are the main disadvantages of AI in hiring and recruitment?",["Compliance and accuracy","Speed and cost","It attracts too many applicants","None of the answer choices are correct"],0,"For hiring and recruitment, Derek named compliance and accuracy as the disadvantages."],"e3d-q12":["An employer uses an AI hiring tool that is later found to discriminate against applicants. Who is liable?",["The software vendor only, because the employer did not write the algorithm","The applicant, for agreeing to AI screening","No one, because AI decisions are automatically exempt from discrimination law","The employer, because an AI mistake is still the employer’s liability"],3,"An AI mistake is still the employer’s liability. This has happened in CA, CO, IL, NY and MD."],"e3d-q13":["Which states did Derek Story list as having had AI hiring and discrimination issues?",["TX, FL, OH","Illinois only","CA, CO, IL, NY, MD","WA, OR, NV"],2,"Derek listed CA, CO, IL, NY and MD. Illinois is on the list, but it is not the only state."],"e3d-q14":["Which of the following was NOT one of the AI concerns raised by Bill Gates and Barack Obama?",["Safety and security","A higher minimum wage","Socializing the next generation","Environmental threats"],1,"The concerns were safety and security, socializing the next generation and environmental threats. A higher minimum wage was not one of them."],"e3d-q15":["An operations team starts using AI as a translator. According to Derek Story, what are the good side and the bad side of this use?",["Good: it is free; Bad: it is slow","Good: it removes all risk, because AI translation is always fully accurate; Bad: none","Good: it can translate; Bad: the results depend on knowing how to ask questions","None of the answer choices are correct"],2,"The good side is that AI can translate. The bad side is that results depend on knowing how to ask questions."],"e3d-q16":["Elizabeth Adams, PhD (cited by Derek Story) focuses on fairness, accountability, leadership and ______ in AI.",["algorithmic accuracy","profitability","speed","marketing"],0,"Adams focuses on fairness, accountability, leadership and algorithmic accuracy in AI."],"e3-43":["Employee benefits are best defined as the part of the total compensation package that is:",["Paid in cash on a delayed schedule","Always strictly mandated by federal statute for every employer","Other than pay for time worked","Negotiated exclusively through collective bargaining"],2,"Benefits are the part of total compensation “other than pay for time worked.” The statute option is wrong because most benefits are discretionary."],"e3-44":["A compensation manager preparing a total rewards statement for U.S. private industry workers wants to report the share of total compensation that benefits represent. Which approximate figure should the manager use?",["10%","30%","42%","Federal law caps benefits at 20% of total compensation"],1,"Benefits are about 30% of total compensation. 42% is the ratio to wages and salaries only, the classic distractor."],"e3-45":["The original catalyst for the growth of employee benefits in the 1940s and 1950s is known as:",["ERISA","The Affordable Care Act","Wage and Price Controls","The Shift to a Service Economy"],2,"During WWII and Korea, wage and price controls kept employers from raising wages, so they competed on benefits instead."],"e3-60":["An organization replaces its traditional pension with a defined contribution plan. Which statement best describes who bears the investment risk and what the plan tends to facilitate?",["The employer bears the risk, and the plan encourages retention","The employee bears the risk, and the plan facilitates mobility","Federal law requires the employer to guarantee all investment losses under any defined contribution plan","The employee bears the risk, and the plan encourages retention"],1,"Under DC the employee bears the investment risk, and the plan facilitates mobility (portable, faster vesting). DB is the plan that encourages retention."],"e3-61":["Which of the following does ERISA require?",["Every employer must offer a pension plan","Pension benefits must be fully portable between employers","Employees be eligible for pension plans beginning at age 21","The PBGC must replace 100% of a failed plan’s benefits"],2,"ERISA sets eligibility at age 21. It does not require employers to offer a plan or make benefits portable, and the PBGC guarantees only a basic benefit."],"e3-62":["An HR manager is checking whether the company is covered by the Family and Medical Leave Act (FMLA). Which combination of employer size, radius and leave entitlement applies?",["At least 20 employees within a 50-mile radius; up to 18 weeks of paid leave","At least 50 employees within a 75-mile radius; up to 12 weeks of paid leave","At least 50 employees within a 75-mile radius; up to 12 weeks of unpaid leave","None of the answer choices are correct"],2,"FMLA covers employers with 50 employees within a 75-mile radius and provides up to 12 weeks of UNPAID leave. The “paid” option is the common trap."],"e3-63":["A terminated employee elects COBRA continuation coverage. What is the maximum percentage of the premium the employer may charge the former employee?",["50%, with the employer paying the remainder","100%; federal law prohibits charging any administrative fee","120%","102%"],3,"COBRA allows up to 102%: 100% of the premium plus 2% for administration."],"e3-64":["A health plan that combines HMO and PPO features, letting the person choose which to use at the time of service, is called:",["A Point-of-Service (POS) Plan","An Indemnity Plan","A Health Savings Account","A Consumer-Driven Health Plan"],0,"A point-of-service (POS) plan is the HMO/PPO hybrid, with the choice made at the time of service."],"e3-65":["A warehouse employee is injured on the job and asks HR whether he can sue the employer. Which description of workers’ compensation should HR rely on?",["A state no-fault program under which the covered employee generally cannot sue the employer","A federal no-fault program that preserves the employee’s right to sue","A discretionary benefit offered by about 47% of employers","A federal program financed by employee payroll deductions"],0,"Workers’ compensation is a state, no-fault program, and the covered worker gives up the right to sue the employer."],"e3-67":["A benefit plan under which the employer pays the entire cost and the employee contributes nothing is known as a(n):",["Contributory Plan","Noncontributory Plan","Cafeteria Plan","Defined Contribution Plan"],1,"Noncontributory means the employer pays the entire cost and the employee contributes nothing."],"e3-68":["An employee is injured on the job because of his own carelessness, and his supervisor argues that he should be denied workers’ compensation. Which response is accurate?",["The supervisor is correct; federal law prohibits workers’ compensation for injuries caused by employee negligence","The employee must file for unemployment insurance instead","The employee is eligible only if he can prove the employer was negligent","The employee remains eligible, because workers’ compensation is a no-fault program"],3,"Workers’ comp is no-fault, so an injury caused by the employee’s own carelessness is still covered."],"e3-69":["In most states, unemployment insurance is financed:",["Exclusively by employers","Exclusively through employee payroll deductions","Split 50/50 between employer and employee","Entirely by the federal government"],0,"In most states employers pay the entire cost of unemployment insurance."],"e3-71":["A compensation manager explains to new hires that their retirement plan is a defined benefit plan. Which statement about this plan is accurate?",["The employer’s contribution is defined and the employee bears the investment risk","The benefit is defined and the employer bears the investment risk","The benefit is defined and the employee bears the investment risk","Federal law requires the PBGC to bear all investment risk under every defined benefit plan"],1,"Under DB the benefit is defined and the employer bears the risk. A defined employer contribution with employee risk describes defined contribution."],"e3-72":["An employee’s own contributions to a pension fund:",["Vest immediately and irrevocably","Follow the same vesting schedule as the employer’s contributions","Never vest until the employee reaches retirement age","Are automatically forfeited if the employee leaves before retirement"],0,"An employee’s own contributions vest immediately and irrevocably. Only the employer’s contributions follow a vesting schedule."],"e3-74":["A percentage of the bill that the employee pays after the deductible is called:",["Copay","Premium","Coinsurance","Experience Rating"],2,"Coinsurance is a percentage of the bill after the deductible. A copay is the flat dollar amount paid per office visit."],"e3-76":["A compensation analyst wants to tell managers how much benefits add on top of every $1 of wages and salaries. Which figure should the analyst use?",["About 12 cents","About 30 cents","About 42 cents","None of the answer choices are correct"],2,"Benefits add about 42 cents per dollar of wages and salaries. 30% is benefits’ share of total compensation, which uses a different denominator."],"e3-77":["A manager argues that benefits are cheaper to provide than the same amount in cash because of group rates and tax treatment. Which reason for the growth of employee benefits is the manager describing?",["Wage and Price Controls","Unions","Government Impetus","Cost (Including Tax) Effectiveness"],3,"“Tax advantaged” and “cheaper than cash” point to cost (including tax) effectiveness."],"e3-78":["An HR analyst discovers that employees rate benefits as important but underestimate what they cost. What should the organization do to close this gap?",["Add another benefit to raise perceived value","Improve benefits communication and give employees more responsibility","Cut benefits and raise wages","Switch to a noncontributory plan, which automatically eliminates the gap"],1,"Low perceived value is fixed with better communication (and more employee responsibility), not by adding another benefit."],"e3-79":["The benefit planning objective that judges a benefit by the employee’s financial exposure with versus without it is called:",["Adequacy","Competitiveness","Cost Effectiveness","Equity"],0,"Adequacy asks whether the benefit is enough to matter to the employee’s financial exposure."],"e3-80":["In an organization’s cafeteria plan, employees choose the coverage they already know they will use, driving up the cost of that option. This problem is called:",["Moral Hazard","Experience Rating","Adverse Selection","Cost Shifting"],2,"Adverse selection is the main downside of flexible (cafeteria) plans, along with administration."],"e3-81":["A benefits manager is deciding what goes into the benefit package. Which of the following is an EMPLOYEE factor in that decision?",["Personal needs tied to age, marital status, and dependents","Competitor offerings","Legal requirements","Relationship to total compensation costs"],0,"Employee factors are equity and personal needs. Competitor offerings is an employer factor."],"e3-82":["Which of the following is NOT a discretionary benefit?",["401(k) Plan","Health Insurance","Paid Vacation","Unemployment Insurance"],3,"Unemployment insurance is legally required, along with workers’ comp and Social Security/Medicare. The other options are discretionary."],"e3-83":["A funding approach in which this year’s Social Security contributions immediately pay this year’s beneficiaries is known as:",["Fully Funded","Pay As You Go","Defined Contribution","Experience Rated"],1,"Social Security is pay-as-you-go, which is the core funding problem as the number of workers per retiree falls."],"e3-84":["After a year of heavy layoffs, a company sees its state unemployment tax rate rise. This increase is due to:",["Vesting","Adverse Selection","Experience Rating","COBRA"],2,"Under experience rating, an employer’s unemployment tax rate depends on its own layoff history."],"e3-85":["Which law limits denying coverage for a preexisting condition and has strict privacy rules?",["HIPAA","FMLA","COBRA","ERISA"],0,"HIPAA (1996) covers preexisting conditions and privacy."],"e3-86":["An employee asks HR, “How long until the company’s match is mine?” This is a question about:",["Portability","Coinsurance","Experience Rating","Vesting"],3,"Vesting is ownership earned over time. Portability is moving the money to a new employer."],"e3-87":["A health plan that restricts employees to a fixed network of providers in exchange for low cost is called a(n):",["Indemnity Plan","PPO","HMO","None of the answer choices are correct"],2,"Restricting employees to network providers only, at low cost, describes an HMO."],"e3-88":["An employee wants a health account that she owns and that rolls over from year to year. Which account fits?",["FSA, because unused funds automatically roll over without limit","HSA","PPO","COBRA account"],1,"HSA money belongs to the employee and rolls over. FSA money is use-it-or-lose-it."],"e3k-q1":["Guest speaker Kathleen Hermacinski described four ways benefits shape an organization. Which of the following is NOT one of them?",["Total Compensation","Risk Allocation","Stock Price","Compliance"],2,"Benefits shape total compensation, risk allocation, compliance and talent. Stock price is not on the list."],"e3k-q2":["According to guest speaker Kathleen Hermacinski, an advantage or value gained from something (e.g., healthcare, paid time off) is called a:",["Bonus","Payroll Tax","Incentive","Benefit"],3,"Kathleen defined a benefit as an advantage or value gained from something, such as healthcare or paid time off."],"e3k-q3":["A new hire asks HR whether workers’ compensation premiums will be taken out of her paycheck. Which answer is accurate?",["Yes; the employee pays through payroll deductions","Premiums are split 50/50 between employer and employee","No; the employer pays, and premiums are not deducted from the employee’s pay","The federal government pays all premiums"],2,"Workers’ comp is employer funded. Premiums are not taken out of paychecks."],"e3k-q4":["An employee cuts a finger on a fan at work. Under workers’ compensation, what procedure should the supervisor follow first?",["Document and report the injury","Take no action, since the injury was the employee’s fault","Advise the employee to sue the employer","Have the employee file under COBRA"],0,"Workers’ comp covers work injuries, and the first step is to document and report the injury. It is no-fault, so blame doesn’t matter."],"e3k-q5":["A 1099 independent contractor is hurt while working on a job for a company. Which statement generally applies?",["The company’s workers’ comp must always cover anyone injured on its jobs","COBRA covers the contractor","FMLA covers the contractor","The contractor falls outside the employer’s workers’ comp, so the company isn’t responsible"],3,"A 1099 contractor doesn’t work FOR the employer, just on the job, so contractors generally fall outside employee workers’ comp."],"e3k-q6":["A CFO claims that switching to a self-funded health plan will eliminate all of the employer’s risk. Which response is accurate?",["The CFO is correct; self-funding automatically eliminates all claims risk","The employer pays claims itself, so it carries more claims risk, not none","Federal law requires the insurance carrier to absorb all claims in a self-funded plan","None of the answer choices are correct"],1,"In a self-funded plan the employer pays claims itself, so it carries MORE claims risk, not none."],"e3k-q7":["Which of the following did guest speaker Kathleen Hermacinski list as a fringe benefit?",["Base Salary","Pet Insurance","Overtime Pay","FICA"],1,"Kathleen’s fringe benefits included vision, memberships, catered meals, snacks, pet insurance and EAP (mental health). Base salary and overtime are pay, and FICA is a tax."],"e3k-q8":["An Employee Assistance Program (EAP) mainly offers:",["Retirement matching","Extra vacation days","Stock options","Mental health and personal support"],3,"An EAP provides mental health support and was listed as a fringe benefit."],"e3k-q9":["A growing company wants to know when the ACA employer mandate will apply to it. The mandate applies to employers with at least:",["15 employees","20 employees","50 full-time equivalent employees","100 employees"],2,"The ACA employer mandate applies at 50+ full-time equivalents (an “applicable large employer”)."],"e3k-q10":["An HR analyst is testing whether the organization’s health coverage is “affordable” under the ACA for 2026. The employee’s cost for self-only coverage must be no more than:",["7.65% of income","9.96% of household income","4.95% of income","$99.60 per year"],1,"The 2026 affordability threshold is 9.96%. Employers use IRS “safe harbors” (W-2 wages, rate of pay, or federal poverty line) to prove it."],"e3k-q11":["Under the Family and Medical Leave Act (FMLA), an eligible employee can take up to 12 weeks of leave that is:",["Unpaid, but the job is protected","Paid at full salary, as federal law strictly mandates","Paid at 2/3 salary","Only for the employee’s own illness"],0,"FMLA leave is UNPAID with job protection. It is easy to mis-hear as “paid,” but the exam wants unpaid."],"e3k-q12":["After a qualifying loss of coverage (e.g., job loss, cut hours), COBRA allows a worker to:",["Receive free insurance for life","Keep group health insurance, with the worker paying up to 102% of the premium","Take 12 weeks of leave","Avoid FICA"],1,"COBRA lets the person continue group insurance after a qualifying event. The person pays, up to 102%."],"e3k-q13":["The account that is tied to a high-deductible health plan is called a(n):",["FSA","DC FSA","HSA","EAP"],2,"An HSA (Health Savings Account) is paired with a high-deductible plan, and the money rolls over."],"e3k-q14":["An employee enrolls in a Dependent Care FSA (DC FSA). Which expense is the account designed to cover?",["Doctor copays","Retirement savings","Dental cleanings","Day care for dependents"],3,"A Dependent Care Flexible Spending Account is optional and pays for day care with pre-tax money."],"e3k-q15":["FICA stands for:",["Federal Insurance Contributions Act","Federal Income Compensation Act","Fair Income Credit Account","Federal Insurance Coverage Allowance"],0,"FICA is the Federal Insurance Contributions Act: Social Security 6.2% + Medicare 1.45%."],"e3k-q32":["According to guest speaker Kathleen Hermacinski, the 2026 wage limit for Social Security (6.2%) is:",["$168,600","$176,100","$184,500","No limit"],2,"Social Security stops at the $184,500 wage base. Medicare (1.45%) applies to ALL wages, with no cap."],"e3k-q33":["A payroll specialist processes pay for an executive whose 2026 wages exceed $184,500. Which FICA tax continues to apply to all of the executive’s wages?",["Social Security","Medicare","FUTA","SUTA"],1,"Medicare (1.45%) applies to all wages. Social Security stops at the $184,500 wage base (2026)."],"e3k-q34":["A compensation manager is budgeting for a new hire at a $60,000 salary. What does the EMPLOYER pay in FICA on top of the salary?",["$4,590","$3,720","$870","$9,180"],0,"Employer Social Security 6.2% × $60,000 = $3,720 plus Medicare 1.45% × $60,000 = $870, for $4,590 above the salary. $9,180 would be employer + employee."],"e3k-q35":["In a fully insured health plan, the employer:",["Pays claims as they happen","Must always buy stop-loss coverage","Has no costs","Pays the carrier a fixed premium"],3,"Fully insured means a fixed premium to the carrier: predictable, less claims risk, less plan control, and subject to state premium tax."],"e3k-q36":["An organization is comparing a self-funded health plan with a fully insured plan. Which of the following is true of the self-funded plan?",["Fixed, predictable cost","More claims risk, more control, and the employer keeps the savings","Less plan control","Subject to state premium tax"],1,"Self-funded means the employer pays claims + admin, so cost is variable, with more risk, more control and the savings kept. The other options describe fully insured."],"e3k-q37":["Insurance on top of insurance that protects a self-funded employer from very large claims is called:",["Stop-Loss Coverage","COBRA Extension","Employee Deductible","Unemployment Insurance"],0,"Stop-loss protects a self-funded employer from very large claims: “insurance on top of insurance.”"],"e3k-q38":["An employee asks how long her child can stay on her health plan. Under the ACA, a child can stay on a parent’s plan until age:",["18","21","26","None of the answer choices are correct"],2,"Under the ACA a child can stay on a parent’s plan until 26."],"e3k-q39":["A child is covered by both parents’ plans. Under the birthday rule, which plan is primary?",["The older parent’s plan","The father’s plan","The plan with the lower premium","The plan of the parent whose birthday comes first in the calendar year"],3,"Under the birthday rule, whoever’s birthday comes first in the year (month and day, not age) is primary."],"e3k-q40":["An event that lets an employee change insurance outside open enrollment (e.g., death, marriage, court order) is known as a:",["Qualifying Life Event (QLE)","COBRA Event","Stop-Loss Claim","Safe Harbor"],0,"Marriage, death and court orders are qualifying life events. Otherwise, changes wait for open enrollment."],"e3k-q41":["Unemployment insurance is best described as:",["A federal-only program paid by employees","A federal–state program that replaces part of lost wages for eligible workers","A benefit paid by the worker’s new employer","The same program as workers’ comp"],1,"Unemployment insurance is a federal–state program that replaces part of lost wages for eligible workers, with extra for dependents in Illinois."],"e3k-q42":["A new Illinois employer is estimating its state unemployment tax. According to guest speaker Kathleen Hermacinski, which taxable wage base and new-employer rate apply?",["$7,000 and 0.6%","$14,250 and 7.65%","$14,250 and 3.35%","$184,500 and 6.2%"],2,"Illinois: wage base $14,250, new-employer rate 3.35%, with rates ranging about 0.75%–7.05%. $7,000 and 0.6% is FUTA."],"e3k-q43":["An Illinois organization is posting a job opening. Under Illinois pay transparency rules, what must the posting include?",["Only the job title","Every current employee’s pay","The previous incumbent’s salary","The salary range and a general description of benefits"],3,"Postings need the pay range and a reasonable benefits description, and internal candidates must be told about the opening."],"e3k-q44":["According to guest speaker Kathleen Hermacinski, Illinois paid leave accrues at:",["1 hour per 40 hours worked","1 hour per 20 hours worked","1 day per month","Nothing until year 2"],0,"Illinois paid leave accrues at 1 hour for every 40 hours worked, and employers can also “front load” the hours."],"e3k-q45":["An employee gets hurt at work, and the supervisor asks who pays for the workers’ comp coverage. Which answer is correct?",["The employee, as state law strictly mandates","The employer","Unemployment insurance","Medicare"],1,"Employers pay for workers’ comp."],"e3-1":["A compensation manager reviews an employee whose compa-ratio is 1.32. Which of the following best describes this employee’s pay?",["Paid below the midpoint, but within the ideal range","Paid at the midpoint, since compa-ratios are always rounded to 1.0","Paid above the midpoint and outside the ideal range (0.75–1.25)","Federal law prohibits a compa-ratio above 1.25, so the employee is automatically misclassified"],2,"Above 1.0 means paying above average, and the ideal range is 0.75–1.25, so 1.32 falls outside it. Nothing about a high compa-ratio means the job is misclassified."],"e3-5":["A compa-ratio helps an organization understand how it pays employees relative to which two areas?",["Seniority and Merit","Internal Pay Policy and Market Value","Base Pay and Bonuses","Federal and state law, which strictly mandate pay at the midpoint"],1,"The slide lists two areas: 1. Internal Pay Policy and 2. Market Value."],"e3-6":["The range of compa-ratios considered ideal is:",["0.50 – 1.00","0.90 – 1.10","1.00 – 1.50","0.75 – 1.25"],3,"The slide gives the Ideal Compa-Ratio Range as .75 – 1.25."],"e3-7":["An HR analyst calculates a compa-ratio of exactly 1.0. What does this indicate about how the organization is paying?",["At average","Below average","Above average","Outside the ideal range, which automatically requires a pay freeze"],0,"A compa-ratio of 1.0 means the organization is paying at average; below 1.0 is below average and above 1.0 is above average."],"e3-8":["An organization finds that several employees have HIGH compa-ratios relative to its internal pay policy. What can HR do internally?",["Give these employees more frequent increases","“Freeze” employee increases to bring them more in line with pay policy","Reclassify these employees as independent contractors","Lower the range minimum, which automatically eliminates high compa-ratios"],1,"For high compa-ratios, the slide says HR can “freeze” employee increases to bring them more in line with the pay policy."],"e3-9":["A compensation manager discovers several employees with LOW compa-ratios relative to internal pay policy. What procedure does the course suggest?",["Freeze their pay until the next review cycle","Move them to a lower pay grade","Work on bringing these employees in line with internal pay policy","Take no action, because a low compa-ratio is always ideal"],2,"For low compa-ratios, the slide says HR can work on bringing these employees in line with the internal pay policy; freezing is the response to HIGH ratios."],"e3-10":["Which of the following is a caveat the course gives about interpreting high compa-ratios?",["High compa-ratios always mean an employee is overpaid","High compa-ratios only occur in executive positions","The FLSA prohibits any compa-ratio above 1.25","Highly experienced, long-tenured employees may have much higher pay, among other variables"],3,"The slide’s caveat is that highly experienced, long-tenured employees may have much higher pay, among other variables, so a high ratio is not automatically overpayment."],"e3-11":["A compensation manager compares the company’s pay with market value and finds a HIGH compa-ratio. Which conclusion is most appropriate?",["The company is likely attracting top talent, but may consider decreasing pay depending on how far above market it is","The company is paying below market","The company must freeze pay immediately under federal law","The company is out of FLSA compliance"],0,"A high external compa-ratio means paying above market value: likely attracting top talent, but the company may want to consider decreasing pay depending on how far above it is."],"e3-12":["An HR analyst finds that an employee earns $46,750 in a pay grade with a $55,000 midpoint. What is the employee’s compa-ratio?",["0.72","0.85","1.18","None of the answer choices are correct"],1,"46,750 ÷ 55,000 = 0.85: below average but inside the 0.75–1.25 ideal range. 1.18 comes from dividing the wrong way (midpoint ÷ pay)."],"e3-46":["An employee’s actual pay is $54,000, and the midpoint of her pay range is $60,000. What is her compa-ratio, and what does it indicate?",["1.11, paying above average","0.90, paying above average","0.90, paying below average","1.11, paying below average"],2,"54,000 ÷ 60,000 = 0.90, and below 1.0 means paying below average. 1.11 comes from dividing the midpoint by pay."],"e3-47":["An HR analyst finds that an employee’s compa-ratio is 1.38 relative to internal pay policy. What procedure should the analyst recommend?",["Immediately cut the employee’s pay to the midpoint, as is legally required","Freeze increases, while considering the employee’s tenure and experience","Promote the employee to the next pay grade","Take no action, since 1.38 is within the ideal range"],1,"Freeze increases, keeping in mind the slide’s caveat about long-tenured, highly experienced employees. 1.38 is outside the 0.75–1.25 ideal range, so doing nothing is wrong."],"e3-66":["A compa-ratio is calculated by dividing an employee’s actual pay by:",["The minimum of the pay range","The maximum of the pay range","The midpoint of the pay range (or the market rate)","None of the answer choices are correct"],2,"Divide actual pay by the midpoint (or the market rate), never the minimum."],"e3-89":["A compensation manager reviews a pay grade in which three employees earn $52,000, $55,000 and $61,000, and the grade midpoint is $58,000. What is the group compa-ratio?",["0.90","0.97","1.00","1.03"],1,"Average first: 168,000 ÷ 3 = 56,000. Then 56,000 ÷ 58,000 = 0.97."],"e3-90":["An employee has a compa-ratio of 1.12 in a pay grade with a $64,000 midpoint. Her actual pay is:",["$57,143","$64,000","$76,800","$71,680"],3,"Actual pay = CR × midpoint = 1.12 × 64,000 = $71,680. $57,143 comes from dividing the midpoint by the compa-ratio instead of multiplying."],"e3-91":["When an employee’s compa-ratio is well ABOVE market, the organization is likely:",["Attracting top talent, but may consider decreasing pay depending on how far above market it is","Violating the FLSA, which prohibits above-market pay","Legally required to freeze the employee’s pay","Paying below average"],0,"Above market means the organization is likely attracting top talent, but it may consider decreasing pay depending on how far above market it is."],"e3-3":["According to the course, base salary accounts for approximately what share of CEO pay?",["8.7%","30%","50%","81%"],0,"Base salary accounted for just 8.7%; long- and short-term incentives make up the bulk."],"e3-36":["Which of the following is NOT one of the five elements of an executive compensation package?",["Base Salary","Long-Term Incentives","Overtime Pay","Perquisites"],2,"The five elements are base salary, short-term incentives/bonuses, long-term incentives, benefits and perquisites; overtime pay is not one of them."],"e3-37":["A board of directors awards its CEO stock options and stock grants. These rewards are examples of:",["Short-Term Incentives","Perquisites","Benefits","Long-Term Incentives"],3,"Stock options and stock grants are long-term incentives."],"e3-38":["The bulk of CEO pay comes from:",["Base salary, which always makes up the majority of an executive package","Long-term and short-term incentives","Benefits","Perquisites"],1,"Long-term and short-term incentives account for the bulk of CEO pay; base salary is only about 8.7%."],"e3-39":["A compensation committee adopts an annual bonus plan for the company’s executives. These bonuses are designed primarily to:",["Replace base salary entirely","Satisfy ERISA, which legally mandates executive bonuses","Motivate better short-term performance","Reduce the company’s FICA taxes"],2,"Executive annual bonuses are designed to motivate better short-term performance."],"e3-40":["The three common measures used for executive bonuses are:",["Profit, Revenue, and Cash Flow","Tenure, Merit, and Skill","Stock, Benefits, and Perks","Turnover, Absenteeism, and Safety"],0,"The three common measures are profit, revenue and cash flow."],"e3-41":["Non-financial measures used in executive bonus plans can be:",["Federal, state, or local","Strategic, individual, or discretionary","Weekly, monthly, or yearly","Fixed, variable, or deferred"],1,"Non-financial measures can be strategic, individual or discretionary."],"e3-42":["An organization provides one of its executives with a company car and a club membership. These rewards are known as:",["Long-Term Incentives","Short-Term Incentives","Base Salary","Perquisites"],3,"Perks such as these are perquisites, the fifth element of the executive package."],"e3-58":["A company provides an executive with a company car that the executive’s spouse is also entitled to use. Which element of executive compensation is this?",["A Perquisite","A Benefit","A Long-Term Incentive","A Short-Term Incentive"],0,"This is a perquisite: perks attach to the position and typically extend to dependents."],"e3-59":["A compensation committee is designing an executive bonus plan and wants to use the three common financial measures. Which measures should it use?",["Revenue, headcount, and market share","EPS, turnover, and customer satisfaction","Profit, compa-ratio, and labor cost","Profit, revenue, and cash flow"],3,"The three common financial measures are profit, revenue and cash flow."],"e3-75":["Which of the following best describes how bonuses have changed as a portion of executive pay over time?",["Bonuses have become a larger portion of executive pay","Bonuses have become a smaller portion of executive pay","Bonuses are legally capped at a fixed share of executive pay","None of the answer choices are correct"],1,"Bonuses have become a smaller portion of executive pay, not a larger one."],"e3-99":["A compensation analyst finds that an executive’s base salary is $522,000, the typical 8.7% of the total package. The total package is about:",["$4.5 million","$5.2 million","$6.0 million","$8.7 million"],2,"Total = 522,000 ÷ 0.087 = $6,000,000."],"e3-100":["Stock options and stock grants fall under which executive pay component?",["Base Salary","Short-Term Incentives","Long-Term Incentives","None of the answer choices are correct"],2,"Stock options and stock grants are long-term incentives."],"e3-101":["A compensation committee designs an executive bonus plan that mixes financial measures (e.g., profit, revenue) with non-financial measures. This reflects:",["A Cost-Centered Approach","Experience Rating","A Defined Benefit Plan","A Balanced Scorecard Approach"],3,"Mixing financial and non-financial measures is a balanced scorecard approach, which is preferred."],"e3-2":["An organization engages a worker who uses their own tools, is paid per project, and serves several other clients at the same time. Under the common-law test, this worker is most likely classified as a(n):",["Core Employee","Leased Employee","Independent Contractor","Part-Time Employee who must automatically receive employer benefits"],2,"Using their own tools, being paid by the project, and working for more than one business are contractor factors on the common-law test. Leased employees work for a staffing agency, not for themselves."],"e3-4":["Part-time workers who resign from an organization are eligible to purchase continued health insurance coverage under:",["COBRA","ERISA","PPACA, which strictly mandates employer-paid coverage for all part-time workers","FUTA"],0,"Following resignation, part-time workers are eligible to purchase health insurance under COBRA rules. Part-time workers are not protected under PPACA."],"e3-24":["Individuals who do not have an implicit or explicit contract for ongoing employment are known as:",["Core Employees","Nonexempt Employees","Contingent (Flexible) Workers","Exempt Employees under the FLSA duties test"],2,"Flexible/contingent workers do not have an implicit or explicit contract for ongoing employment; core employees plan on long-term relationships."],"e3-25":["An HR analyst reviews the status of a staff member who will not continue her employment because she is returning to school. How should the analyst classify this individual?",["As a contingent worker, because she has no expectation of continued employment","As not a contingent worker, because she does not expect to continue for personal reasons","As a leased employee of a staffing agency","As an independent contractor under the common-law test"],1,"People who do not expect to continue for personal reasons, such as returning to school or retirement, are not contingent workers. Her short remaining tenure is a personal choice, not the absence of an ongoing-employment contract."],"e3-26":["Two or more part-time employees performing one job is called:",["Telecommuting","Compressed Workweek","Employee Leasing","Job Sharing"],3,"Job sharing is two or more part-timers performing one job; it reduces costs, increases flexibility, maintains productivity, and may increase loyalty."],"e3-27":["Which of the following is NOT a listed reason for the rise in use of flexible workers?",["Economic recessions","New federal overtime rules","International competition","The shift from a manufacturing to a service economy"],1,"The slide lists recessions, international competition, and the shift from manufacturing to a service economy; new federal overtime rules are not on the list."],"e3-28":["A compensation manager benchmarking benefits wants to compare part-time and full-time workers. Approximately what share of part-time workers have retirement benefits, compared with full-time workers?",["About 81% of part-time workers vs. 38% of full-time workers","About 38% of part-time workers vs. 81% of full-time workers","About 50% of each, because Federal law requires equal retirement access","About 8.7% of part-time workers vs. 91% of full-time workers"],1,"Retirement benefits reach about 38% of part-time workers compared to 81% of full-time workers. The first option simply reverses the two figures."],"e3-29":["Employers must allow part-time workers to participate in retirement plans once they meet the age and service requirements of:",["COBRA","PPACA","ERISA","FLSA"],2,"Part-time workers must be allowed to participate after fulfilling the ERISA age and service requirements. COBRA concerns continued health coverage, not retirement plans."],"e3-30":["Part-time workers are NOT protected under which of the following?",["COBRA","ERISA","FICA","PPACA"],3,"For health insurance, part-time workers are not protected under PPACA. They can still purchase COBRA coverage after resigning and must be allowed into retirement plans once ERISA requirements are met."],"e3-31":["An organization offers its employees flextime, compressed workweeks, and telecommuting. These arrangements are collectively known as:",["Flexible Work Schedules","Contingent Worker Types","Perquisites","Payroll Deduction Steps"],0,"Flexible work schedules include flextime, compressed workweeks, and telecommuting. Contingent worker types describe who is employed, not how hours are arranged."],"e3-32":["A company schedules its flexible employees to work during a holiday. Which policy must the company follow?",["Pay them triple time, as Federal law strictly mandates for all holiday work","Automatically convert them to full-time status","Provide them alternative time off","None of the answer choices are correct"],2,"For treatment of paid time off for holidays, companies must provide alternative time off when flexible employees work during holidays."],"e3-33":["An organization pays a worker by the hour, directly supervises the work, and provides the tools used on the job. Under the common-law test, this worker is classified as:",["An Independent Contractor","A Leased Employee","A Consultant","An Employee"],3,"A worker is an employee if the employer controls/supervises, provides tools and location, and pays by the hour or time worked."],"e3-34":["Which of the following factors appears in the economic realities test?",["Intent of the parties","Method of payment","Opportunity for profit or loss (risk)","Type of business"],2,"Economic realities factors are integration, investment in facilities, right to control, risk (profit or loss), skill, and continuing relationship. Intent, method of payment, and type of business are common-law factors."],"e3-35":["An HR analyst finds that a worker has made a substantial investment in the work facilities and equipment. Under the economic realities test, this factor points toward:",["Employee Status","Part-Time Status","Leased Status","Independent Contractor Status"],3,"On the economic realities test, a substantial investment in facilities and equipment points toward contractor status."],"e3-52":["Which of the following individuals is NOT a contingent worker?",["An employee who plans to leave in May to return to graduate school","A part-time cashier","A seasonal warehouse worker hired through December 31","A consultant engaged for a six-month project"],0,"Leaving for personal reasons (e.g., school, retirement) does not make someone contingent; the professor repeated this in the video. Part-timers, seasonal hires, and project consultants lack a contract for ongoing employment."],"e3-53":["A leased employee is legally the employee of:",["The client organization where the work is performed","The staffing agency","Neither, because leased employees are always legally self-employed","Both, jointly and equally under federal law"],1,"A leased employee belongs to the staffing agency: the client pays the agency, and the agency pays the worker."],"e3-54":["An HR director preparing a workforce plan summarizes the three reasons given for the rise in use of flexible workers. Which of the following is NOT one of those reasons?",["Economic recessions","International competition","The passage of the Family and Medical Leave Act","The shift from manufacturing to a service economy"],2,"The three reasons are recessions, international competition, and the manufacturing-to-service shift; the FMLA is not one of them."],"e3-55":["Regarding benefits for part-time workers, which of the following statements is accurate?",["Federal law requires employers to offer them health insurance under PPACA","They are legally ineligible for COBRA coverage after resignation","Retirement is a legally required benefit for all workers","Employers must allow them into retirement plans once ERISA age and service requirements are met"],3,"Employers must allow retirement participation once ERISA thresholds are met. Part-timers are not protected under PPACA, can buy COBRA coverage, and retirement is a discretionary benefit."],"e3-56":["“Investment in facilities” and “risk of profit or loss” are factors found in:",["The economic realities test only","The common-law test only","Both tests","Neither test"],0,"These are economic realities test factors only; neither appears on the common-law list."],"e3-57":["An organization adopts a compressed workweek for its staff. Which form does a compressed workweek most commonly take?",["Five 7-hour days","Four 10-hour days","Six 6-hour days","Three 8-hour days"],1,"Four 10-hour days is the most common form. Three 12-hour days (36 hours) also appears, but 4×10 is most common."],"e3-70":["Which of the following statements about part-time employees is accurate?",["They are considered contingent workers","They are always considered core employees","They are legally classified as independent contractors","None of the answer choices are correct"],0,"Part-time employees are considered contingent workers. Core employees are those who plan on a long-term relationship."],"e3-73":["A private organization’s HR manager is reviewing its holiday policy. Which statement about federal holidays is accurate?",["Federal law requires all private organizations to close on federal holidays","Private organizations are not legally required to close on federal holidays","Private organizations must close on federal holidays only if they employ flexible workers","None of the answer choices are correct"],1,"Private organizations are not legally required to close on federal holidays. That is exactly why the rule to provide alternative paid time off exists."],"e3-95":["A retailer hires three workers for the holidays with a definite stop date. The stop date is what makes these workers:",["Exempt Employees","Core Employees","Leased Employees","Contingent Workers"],3,"A definite stop date means there is no contract for ongoing employment, so the workers are contingent."],"e3-96":["Two part-time employees split one full-time job. Which of the following is NOT one of the four listed effects of job sharing?",["Reduces costs","Increases flexibility","Guarantees benefits eligibility under federal law","May increase loyalty"],2,"The four effects are: reduces costs, increases flexibility, maintains productivity, and may increase loyalty. Job sharers typically are not benefit-eligible."],"e3-97":["“Intent” and “method of payment” are factors on which test?",["The economic realities test only","The FLSA duties test","Both tests","The common-law test only"],3,"Intent, tools, supervision, method of payment, type of business, and working for more than one firm are common-law factors only."],"e3-98":["An employee drops her child off at 8:15, starts work at 8:30, leaves at 3:15, and finishes her hours remotely. This arrangement is called:",["Flextime","Compressed Workweek","Job Sharing","Telecommuting only"],0,"Working different times of the day is flextime. A compressed workweek fits full-time hours into fewer days, which is not happening here."],"e3-13":["The process of compensating employees for their work, which involves calculating earnings, deductions and taxes and issuing payments, is called:",["Total Rewards","Payroll","Pay Structure","Compa-Ratio Analysis"],1,"Payroll is the process of compensating employees: calculating earnings, deductions and taxes, and issuing payments. Total Rewards is the broader package, not the payment process."],"e3-14":["After a payroll specialist subtracts all deductions from an employee’s total earnings, the remaining take-home amount is called:",["Gross Pay","Base Pay","Net Pay","Pay Level"],2,"Net pay is take-home pay after all deductions. Gross pay is total earnings before deductions."],"e3-15":["An organization is redesigning its payroll workflow. Which step must occur FIRST in the payroll process?",["Calculations","Time Collection","Review & Audit","Disbursement, since Federal law requires employees to be paid before hours are verified"],1,"The process runs 1 Time collection → 2 Approval & entry → 3 Calculations → 4 Review & audit → 5 Disbursement → 6 Reporting."],"e3-16":["The fourth step of the payroll process, in which the payroll is checked for accuracy, is called:",["Approval & Entry","Time Collection","Disbursement","Review & Audit"],3,"Review & Audit is step 4, the accuracy check, coming after calculations and before disbursement."],"e3-17":["A compensation manager is drafting a payroll recordkeeping policy. According to the course slides, how long should payroll records be maintained?",["At least 3–4 years","At least 1 year, after which they must be destroyed","Federal law requires all payroll records to be kept permanently","Only until the employee leaves the organization"],0,"The slide’s recordkeeping guideline is to maintain payroll records for at least 3–4 years."],"e3-18":["Which of the following is NOT withheld from the employee’s paycheck but is instead paid by the employer?",["Federal income tax","FUTA & SUTA (federal and state unemployment taxes)","State income tax","The employee share of FICA"],1,"The employer pays its own portion of FICA plus FUTA & SUTA. Income taxes and the employee share of FICA are withheld from the employee."],"e3-19":["The total employee payroll tax rate for Social Security and Medicare combined is:",["6.20%","15.30%","1.45%","7.65%"],3,"Social Security 6.20% + Medicare 1.45% = 7.65% in total payroll taxes withheld from the employee."],"e3-20":["An employee earns $1,000 in gross pay for the period. How much Social Security and Medicare should the payroll specialist withhold and send to the federal government?",["$62.00","$76.50","$14.50","$100.00"],1,"$62.00 Social Security + $14.50 Medicare = $76.50, which is sent to the federal government. $62.00 alone leaves out Medicare."],"e3-21":["An HR analyst reviews Angela’s paycheck: $2,000 gross pay, $124 Social Security, $29 Medicare, $237 income tax and a $50 retirement contribution. What is her net pay?",["$1,610","$1,763","$1,560","$1,847"],2,"2,000 − 124 − 29 − 237 − 50 = $1,560. Her employer sends $390 to the federal government and $50 to the retirement fund; $1,610 forgets the retirement deduction."],"e3-22":["A payroll audit finds that an organization paid several workers on a 1099 when they should have been W-2 employees. This is an example of which common payroll mistake?",["Misclassifying Employees (W-2 vs 1099)","Pay Compression","Benchmark Conversion","None of the answer choices are correct"],0,"Misclassifying employees (W-2 vs 1099) is listed among common payroll challenges, along with incorrect tax calculations, late filings, poor documentation and manual entry errors."],"e3-23":["Workday, ADP, Paychex and Gusto are examples of:",["Salary Survey Firms","Incentive Plans","HRIS & Payroll Systems","Unemployment Taxes"],2,"These are payroll systems and technology (Workday, ADP, Paychex, Gusto, etc.)."],"e3-48":["A new payroll clerk claims that 15.30% must be withheld from each employee’s pay for FICA. What is the correct total FICA rate withheld from the employee?",["6.20%","15.30%, because Federal law requires the employee to pay both shares","1.45%","7.65%"],3,"6.20% + 1.45% = 7.65%. 15.30% is the employee and employer shares combined."],"e3-49":["A compensation manager is explaining which payroll costs fall on the organization alone. Which of the following is paid by the employer only?",["FUTA and SUTA","Federal income tax withholding","The employee’s share of Medicare","A 401(k) elective deferral"],0,"FUTA and SUTA are employer-only. The employer matches FICA, but the employee pays FICA too."],"e3-50":["In the payroll process, the step that comes immediately before disbursement is:",["Time Collection","Review & Audit","Calculations","Reporting"],1,"Time collection → approval & entry → calculations → review & audit → disbursement → reporting."],"e3-51":["A worker who receives a Form 1099 rather than a W-2 is being treated as a(n):",["Exempt Employee","Leased Employee","Independent Contractor","Part-Time Employee"],2,"A 1099 means independent contractor. Misclassifying W-2 vs. 1099 is a listed common payroll mistake."],"e3-92":["A newly hired employee needs to tell the employer how much income tax to withhold from each paycheck. Which form should HR have the employee complete at hire?",["W-2","I-9","1099","W-4"],3,"The W-4 goes in at hire; the W-2 comes out at year end; the 1099 is for contractors."],"e3-93":["On $1,000 of earnings, the total Social Security and Medicare withheld from the employee is:",["$76.50","$62.00","$153.00","None of the answer choices are correct"],0,"$62.00 Social Security + $14.50 Medicare = $76.50 (7.65%). $153.00 would double-count the employer’s matching share."],"e3-94":["A payroll specialist has already subtracted Social Security from an employee’s pay and now needs to calculate Medicare. The 1.45% Medicare rate should be applied to:",["Pay left after Social Security, since each tax must always come off the running balance","Gross pay","Net pay","Pay after income tax"],1,"Percentages come off gross pay, never off a running balance."],"e3p-q1":["In the payroll deduction flow, the first category subtracted after gross pay is:",["Taxes","After-Tax Deductions","Garnishments, which federal law requires to be taken before anything else","Before-Tax Deductions"],3,"Gross → before-tax deductions → taxes → after-tax deductions → net pay."],"e3p-q2":["An employee elects to contribute to a Roth 401(k) through payroll. On the payroll deduction flowchart, this contribution is classified as a(n):",["Before-Tax Deduction","After-Tax Deduction","Employer-Paid Tax","Part of Gross Pay"],1,"A Roth contribution is after-tax, so it doesn’t lower taxes; a traditional 401(k) is before-tax. Same account family, opposite layer."],"e3p-q3":["Which of the following is a before-tax deduction on the payroll flowchart?",["Union Dues","Wage Garnishment","Charitable Giving","HSA Contribution"],3,"Before-tax: health insurance, 401(k)/HSA/FSA, commuter benefits. Union dues, garnishments and charity are after-tax."],"e3p-q4":["Which of the following is NOT a before-tax deduction on the payroll flowchart?",["Union Dues","Health Insurance Premium","Traditional 401(k)","Commuter Benefits"],0,"Union dues are after-tax, along with Roth 401(k), garnishments and charity. The other three are before-tax."],"e3p-q5":["An employee asks an HR specialist why a before-tax deduction saves the employee money. Which explanation is most accurate?",["It is paid entirely by the employer","It is automatically refunded in full at year end","It lowers taxable income, so less income tax is withheld","Federal law exempts it from Social Security and Medicare in every case"],2,"Before-tax deductions come out before income tax is figured, shrinking taxable pay. In the prof’s method FICA still comes off gross."],"e3p-q6":["The U.S. federal income tax is best described as:",["Progressive and marginal, with each slice of income taxed at its own rate","Flat, with one rate applied to all income","A fixed 4.95% on all taxable income","A tax paid only by the employer"],0,"Each slice of taxable income is taxed at its bracket’s rate; you never apply one rate to the whole amount. The flat 4.95% is Illinois."],"e3p-q7":["A single employee has $40,000 of taxable income under the 2025 brackets. What is the federal income tax?",["$4,000","$4,800","$8,800","$4,562"],3,"12% bracket: 1,193 + 0.12 × (40,000 − 11,925) = 1,193 + 3,369 = $4,562. $4,800 wrongly applies 12% to the whole amount."],"e3p-q8":["A payroll analyst computes federal income tax on $49,000 of taxable income by multiplying the entire amount by 22%. Using the bracket table correctly, what is the federal income tax?",["$10,780.00","$5,880.00","$5,694.50","$4,900.00"],2,"22% bracket: 5,579 + 0.22 × (49,000 − 48,475) = 5,579 + 115.50 = $5,694.50. 22% × 49,000 = $10,780 is the trap."],"e3p-q9":["An employee with $60,000 of taxable income has a marginal tax rate of:",["12%","22%","24%","None of the answer choices are correct"],1,"$60,000 lands in the $48,476–$103,350 bracket, so the last dollar is taxed at 22%."],"e3p-q10":["Compared with the marginal tax rate, the effective tax rate (total tax ÷ taxable income) is:",["Always higher, because every dollar is taxed at the top rate","Always the same","Unrelated to the marginal rate","Always lower (or equal in the first bracket)"],3,"Lower slices are taxed at lower rates, so the average comes out below the top rate (e.g., $40,000 → $4,562 = 11.4% vs. a 12% marginal rate)."],"e3p-q11":["An HR analyst at an Illinois employer is calculating state income tax withholding. Which rate applies?",["3.00% with brackets","4.95% flat","6.20%","7.65%"],1,"Illinois has a fixed income tax rate of 4.95% with no brackets. 6.20% and 7.65% are FICA rates."],"e3p-q12":["A payroll problem describes an income tax as “fixed,” with one rate applied to all income. Which tax is being described?",["Federal Income Tax","FUTA","Illinois Income Tax","Medicare"],2,"“Flat/fixed” → Illinois. “Progressive/brackets” → federal."],"e3p-q13":["An Illinois employee has monthly taxable pay of $3,650. How much Illinois income tax should be withheld?",["$108.04","$180.68","$226.30","$279.23"],1,"4.95% × 3,650 = $180.68."],"e3p-q14":["Before applying the annual bracket table to a bi-weekly paycheck, the pay must be multiplied by:",["12","24","52","26"],3,"Annualize: monthly ×12 · semi-monthly ×24 · bi-weekly ×26 · weekly ×52. Then divide the annual tax back down."],"e3p-q15":["A single Illinois employee earns $4,000 in monthly gross pay, with $350 in before-tax deductions and a $100 Roth contribution. Using the professor’s method (FICA taken off gross), what is net pay?",["$2,745.15","$2,951.15","$2,645.15","$3,034.00"],2,"FICA 248 + 58; fed 5,018/12 = 418.17; IL 180.68. 4,000 − 350 − 306 − 418.17 − 180.68 − 100 = $2,645.15; $2,745.15 forgets the Roth deduction."],"e3p-q16":["A payroll problem states the amount of income tax withheld for the period. What procedure should the analyst apply?",["Subtract the given withholding amount as is","Recompute it from the bracket table, since given amounts must always be verified","Replace it with 4.95% of gross pay","Ignore it when calculating net pay"],0,"Given a withholding number, just subtract it. Only use the brackets when you have to compute it yourself."],"e3p-q17":["A completed Form W-4 is submitted to:",["The IRS, which is legally required to approve it","The Social Security Administration","The Employer","None of the answer choices are correct"],2,"The form says “Give Form W-4 to your employer”; it tells the employer how much to withhold."],"e3p-q18":["An employee wants an extra $25 withheld from every paycheck. Which part of the federal W-4 should the employee complete?",["Step 4(c)","Step 1","Step 2","Step 3"],0,"Step 4(c) is extra withholding each pay period."],"e3p-q19":["On the 2025 Form W-4, Step 3 (Claim Dependents) provides:",["$500 per child under 17","$1,000 per dependent","One allowance per dependent","$2,000 per qualifying child under 17 and $500 per other dependent"],3,"$2,000 × qualifying children under 17 + $500 × other dependents (income $200k or less; $400k MFJ)."],"e3p-q20":["An employee holds two jobs at the same time. Which step of the federal W-4 applies?",["Step 3: Claim Dependents","Step 2: Multiple Jobs or Spouse Works","Step 4(b): Deductions","Step 5: Sign"],1,"Step 2 covers more than one job or a working spouse (estimator, worksheet → 4(c), or the two-jobs checkbox)."],"e3p-q21":["Which of the following statements about withholding allowances is accurate?",["The federal W-4 still uses allowances","More allowances always means more tax withheld","Neither form uses allowances","The IL-W-4 uses allowances, and more allowances means less tax withheld"],3,"The federal form dropped allowances in the 2020 redesign; the Illinois IL-W-4 still uses them."],"e3p-q22":["An employee who owed no tax last year and expects to owe none wants to claim exempt on the federal W-4. What procedure should the employee follow?",["Write “Exempt” under Step 4(c) and complete only Steps 1(a), 1(b) and 5","Leave the form blank","Check a box in Step 3","Send the form directly to the IRS for approval"],0,"Exempt goes under Step 4(c) with only Steps 1(a), 1(b) and 5 completed, and is allowed only if they owed no tax last year and expect to owe none."],"e3p-q23":["The primary purpose of Form W-4 is to determine:",["The final tax the employee owes","How much is withheld from each paycheck","The employer’s FUTA rate","The employee’s gross pay"],1,"The W-4 sets withholding, not the final tax; the difference settles when the employee files."]};
  const NONE = /^none of the answer/i;
  /* The professor always puts "None of the answer choices are correct" last; keep it there when options are shuffled. */
  window.pinNone = (q, order) => { const i = q.options.findIndex(o => NONE.test(o)); if (i < 0) return order; return order.filter(x => x !== i).concat(i); };
  window.isNoneOption = o => NONE.test(o);
  const apply = d => { if (!d || !d.questions) return; for (const q of d.questions) { const r = R[q.id]; if (!r) continue; q.prompt = r[0]; q.options = r[1]; q.answer = r[2]; q.answerKeyText = r[1][r[2]]; if (r[3]) q.explanation = r[3]; q.profStyle = true; } };
  const seen = new Set();
  for (const d of [window.STUDY_DATA, window.EXAM2_DATA, window.EXAM3_DATA]) if (d && !seen.has(d)) { seen.add(d); apply(d); }
  if (window.EXAM3_DATA) window.EXAM3_DATA.scenarioIds = window.EXAM3_DATA.questions.filter(x => x.prompt.length > 70).map(x => x.id);
})();
